import{_ as a,C as o,o as i,c as s,aj as e,E as n}from"./framework.js";const u=JSON.parse('{"title":"AB Testing | Operations | Admin CMS","description":"Configure A/B experiments for a site: pick an experiment object (page, view, product, etc.) as control A, configure one or more variants B/C… (full object replacement or field…","frontmatter":{"title":"AB Testing | Operations | Admin CMS","description":"Configure A/B experiments for a site: pick an experiment object (page, view, product, etc.) as control A, configure one or more variants B/C… (full object replacement or field…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/operations/ab-testing.html"}]]},"headers":[],"relativePath":"cms/operations/ab-testing.md","filePath":"en/cms/operations/ab-testing.md","lastUpdated":1781010536000}'),d={name:"cms/operations/ab-testing.md"};function l(p,t,g,c,m,h){const r=o("DocImage");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="ab-testing" tabindex="-1">AB Testing <a class="header-anchor" href="#ab-testing" aria-label="Permalink to &quot;AB Testing&quot;">​</a></h1><blockquote><p>Menu: <strong>Operations Center → AB Testing</strong><br> Deep link: <code>/_Admin/system/ab-testing?SiteId={siteGuid}</code></p></blockquote><p>Configure <strong>A/B experiments</strong> for a site: pick an experiment object (page, view, product, etc.) as <strong>control A</strong>, configure one or more <strong>variants B/C…</strong> (full object replacement or field replacement), split visitors by traffic share and optional user conditions, and view reports with a <strong>Goal</strong> as the winning metric.</p><div class="tip custom-block"><p class="custom-block-title">Permission</p><p>Menu permission: <code>abTesting</code>. Enable <strong>Operations Center → AB Testing</strong> (and parent <strong>Operations Center</strong>) in Edit Menu.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Operations Center → AB Testing</strong>.</li><li>Open <strong>Operations Center → AB Testing</strong> on the left.</li></ol><p>The main screen is the experiment list; <strong>Create AB Test</strong> opens a four-step wizard; row actions open <strong>Experiment Report</strong>. Sections below include screenshots.</p>',7)),n(r,{src:"/cms/operations/ab-testing-overview.png",alt:"AB testing list overview",width:"1120"}),t[1]||(t[1]=e('<h2 id="header-and-global-switch" tabindex="-1">Header and Global Switch <a class="header-anchor" href="#header-and-global-switch" aria-label="Permalink to &quot;Header and Global Switch&quot;">​</a></h2><p>Path: <code>/_Admin/system/ab-testing?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable</strong></td><td>Site-wide AB testing master switch (<code>updateAbTestStatus</code>); when off, the frontend stops splitting traffic</td></tr><tr><td>(List area)</td><td>See next section</td></tr></tbody></table>',3)),n(r,{src:"/cms/operations/ab-testing-header.png",alt:"AB testing header and enable switch",width:"1120"}),t[2]||(t[2]=e('<h2 id="list-toolbar" tabindex="-1">List Toolbar <a class="header-anchor" href="#list-toolbar" aria-label="Permalink to &quot;List Toolbar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Create AB Test</strong></td><td>Go to <code>/_Admin/system/ab-testing/create?SiteId=...</code></td></tr><tr><td><strong>Status</strong></td><td>Filter: Draft, Running, Paused, Completed</td></tr><tr><td><strong>Search</strong></td><td>Filter by experiment name or description keywords</td></tr></tbody></table>',2)),n(r,{src:"/cms/operations/ab-testing-list-toolbar.png",alt:"Create button and filters",width:"1120"}),t[3]||(t[3]=e('<h2 id="experiment-list" tabindex="-1">Experiment List <a class="header-anchor" href="#experiment-list" aria-label="Permalink to &quot;Experiment List&quot;">​</a></h2><p>Table columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Experiment Name</strong></td><td>Name + description summary</td></tr><tr><td><strong>Status</strong></td><td>Draft <code>Draft</code>, Running <code>Running</code>, Paused <code>Paused</code>, Completed <code>Completed</code> / <code>Archived</code></td></tr><tr><td><strong>Traffic Share</strong></td><td><strong>Control A</strong> (100% − sum of variant weights) and each <strong>variant</strong> weight percentage</td></tr><tr><td><strong>Progress</strong></td><td>When running: days elapsed / total days and start/end time</td></tr><tr><td><strong>Actions</strong></td><td><strong>View Report</strong> (published and past start time) or open detail; <strong>Delete</strong> experiment</td></tr></tbody></table><p>Click the experiment name area or <strong>View Report</strong> → <a href="#experiment-report-subpage">Experiment Report</a>.</p>',4)),n(r,{src:"/cms/operations/ab-testing-list-table.png",alt:"AB testing experiment list",width:"1120"}),t[4]||(t[4]=e('<h2 id="create-edit-experiment-four-step-wizard" tabindex="-1">Create / Edit Experiment (Four-Step Wizard) <a class="header-anchor" href="#create-edit-experiment-four-step-wizard" aria-label="Permalink to &quot;Create / Edit Experiment (Four-Step Wizard)&quot;">​</a></h2><p>Path: <code>/_Admin/system/ab-testing/create?SiteId=...</code><br> Edit: same path with <code>name={experimentName}</code> query param, prefilled from the list.</p><p>Footer: <strong>Previous</strong>, <strong>Next</strong> / <strong>Save</strong>; <strong>Cancel</strong> returns to the list.</p><h3 id="step-1-basic-info" tabindex="-1">Step 1: Basic Info <a class="header-anchor" href="#step-1-basic-info" aria-label="Permalink to &quot;Step 1: Basic Info&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Experiment Name</strong></td><td>Required, unique identifier</td></tr><tr><td><strong>Experiment Description</strong></td><td>Optional</td></tr><tr><td><strong>Start Date / End Date</strong></td><td>Experiment window; end must be after start</td></tr></tbody></table>',5)),n(r,{src:"/cms/operations/ab-testing-create-step-basic.png",alt:"Create wizard: basic info",width:"1120"}),t[5]||(t[5]=e('<h3 id="step-2-experiment-goal" tabindex="-1">Step 2: Experiment Goal <a class="header-anchor" href="#step-2-experiment-goal" aria-label="Permalink to &quot;Step 2: Experiment Goal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Object Type</strong></td><td>e.g. Page, View, Product, TextContent (<code>ObjectOptions</code>)</td></tr><tr><td><strong>Test Object</strong></td><td>Specific object bound to control A (searchable)</td></tr><tr><td><strong>Winning Metric</strong></td><td>Select a <strong>Goal</strong> (from behavior-analysis traffic settings); <strong>Edit Goal</strong> opens Goal management dialog</td></tr></tbody></table>',2)),n(r,{src:"/cms/operations/ab-testing-create-step-goal.png",alt:"Create wizard: experiment goal and winning metric",width:"1120"}),t[6]||(t[6]=e('<h3 id="step-3-experiment-configuration" tabindex="-1">Step 3: Experiment Configuration <a class="header-anchor" href="#step-3-experiment-configuration" aria-label="Permalink to &quot;Step 3: Experiment Configuration&quot;">​</a></h3><p>Configure each variant:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Replace Entire Object</strong></td><td>Pick another object as variant content</td></tr><tr><td><strong>Replace Fields</strong></td><td>Available when object type supports <code>fieldOverWrites</code>; set field + multilingual replacement values</td></tr></tbody></table><p>You can <strong>Add Variant</strong>, delete variants, and rename variants. Control A is the object from Step 2 and is not selected again here.</p>',4)),n(r,{src:"/cms/operations/ab-testing-create-step-config.png",alt:"Create wizard: variant configuration",width:"1120"}),t[7]||(t[7]=e('<h3 id="step-4-traffic-and-user-assignment" tabindex="-1">Step 4: Traffic and User Assignment <a class="header-anchor" href="#step-4-traffic-and-user-assignment" aria-label="Permalink to &quot;Step 4: Traffic and User Assignment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Block</th><th>Description</th></tr></thead><tbody><tr><td><strong>Traffic Allocation</strong></td><td>Control A share = 100% − all variant weights; set 0–100% per variant; total must not exceed 100%</td></tr><tr><td><strong>User Group Conditions</strong></td><td>Optional: attribute + comparator + value (e.g. country, device); <strong>Add Condition</strong></td></tr></tbody></table>',2)),n(r,{src:"/cms/operations/ab-testing-create-step-traffic.png",alt:"Create wizard: traffic and user assignment",width:"1120"}),t[8]||(t[8]=e('<h2 id="experiment-report-subpage" tabindex="-1">Experiment Report Subpage <a class="header-anchor" href="#experiment-report-subpage" aria-label="Permalink to &quot;Experiment Report Subpage&quot;">​</a></h2><p>Path: <code>/_Admin/system/ab-testing/report?SiteId=...&amp;name={experimentName}</code></p><p>Top bar: back, experiment name, status tag; buttons such as <strong>Edit</strong>, <strong>Start Experiment</strong>, <strong>Pause Experiment</strong>, <strong>Restart</strong>, <strong>End Early</strong> depending on status.</p><h3 id="experiment-details-tab" tabindex="-1">Experiment Details Tab <a class="header-anchor" href="#experiment-details-tab" aria-label="Permalink to &quot;Experiment Details Tab&quot;">​</a></h3><p>Includes:</p><ul><li><strong>Basic Info</strong>: name, description, target users, winning metric, duration and time range</li><li><strong>Experiment Configuration</strong>: control and variant configuration summary</li><li><strong>Traffic Allocation</strong>: share per group</li></ul>',6)),n(r,{src:"/cms/operations/ab-testing-report-detail.png",alt:"Experiment report: Experiment Details tab",width:"1120"}),t[9]||(t[9]=e('<h3 id="experiment-report-tab" tabindex="-1">Experiment Report Tab <a class="header-anchor" href="#experiment-report-tab" aria-label="Permalink to &quot;Experiment Report Tab&quot;">​</a></h3><p>Shown when the experiment is <strong>running or completed</strong>:</p><ul><li><strong>Experiment Conclusion</strong></li><li><strong>Group Data</strong> (performance per variant)</li><li><strong>Confidence Statistics</strong></li></ul><p>Draft or not-yet-started experiments show an empty state (no report data yet).</p>',4)),n(r,{src:"/cms/operations/ab-testing-report-report.png",alt:"Experiment report: Experiment Report tab",width:"1120"}),t[10]||(t[10]=e('<div class="tip custom-block"><p class="custom-block-title">Goals and behavior analysis</p><p>The <strong>winning metric</strong> depends on Goals configured in behavior analysis. If the dropdown is empty, maintain Goals in <strong>Behavior Analysis</strong> (or related traffic settings) first, then add via <strong>Edit Goal</strong> in the create wizard.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Operations Center overview</a></li><li><a href="./page-interaction.html">Page Interaction</a> — anchor click statistics</li><li>Behavior Analysis — Goals, user segments</li></ul>',3))])}const _=a(d,[["render",l]]);export{u as __pageData,_ as default};
